    49|
    50|function generateCode(): string {
    51|  let code = '';
    52|  for (let i = 0; i < CODE_LENGTH; i++) {
    53|    code += randomInt(0, 10).toString();
    54|  }
    55|  return code;
    56|}
    57|
    58|function hashCode(code: string): string {
    59|  const salt = randomBytes(16).toString('hex');
    60|  const digest = scryptSync(code, salt, 32).toString('hex');
    61|  return `${CODE_HASH_PREFIX}:${salt}:${digest}`;
    62|}
    63|
    64|function matchesCode(code: string, storedHash: string): boolean {
    65|  const [algorithm, salt, digest] = storedHash.split(':');
    66|  if (algorithm !== CODE_HASH_PREFIX || !salt || !digest) return false;
    67|  const candidate = scryptSync(code, salt, 32);
    68|  const expected = Buffer.from(digest, 'hex');
    69|  return candidate.length === expected.length && timingSafeEqual(candidate, expected);
    70|}
