    99|async function readStore<T>(file: string, fallback: T): Promise<T> {
   100|  if (isDurableStoreConfigured()) {
   101|    try {
   102|      return await readDurableJson<T>(file, fallback);
   103|    } catch {
   104|      return fallback;
   105|    }
   106|  }
   107|  try {
   108|    const raw = await readFile(file, 'utf8');
   109|    return JSON.parse(raw) as T;
   110|  } catch {
   111|    return fallback;
   112|  }
   113|}
   114|
   115|async function writeStore<T>(file: string, value: T): Promise<void> {
   116|  if (isDurableStoreConfigured()) {
   117|    try {
   118|      await writeDurableJson(file, value);
   119|      return;
   120|    } catch {
   121|      // fall through to filesystem
   122|    }
   123|  }
   124|  await mkdir(path.dirname(file), { recursive: true });
   125|  await writeFile(file, JSON.stringify(value, null, 2), 'utf8');
   126|}
