   128|async function fallbackStoreCode(input: StoreCodeInput, code: string, expiresAt: Date): Promise<void> {
   129|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   130|  const key = codeKey(input.userId, input.type);
   131|  const existing = codes[key];
   132|  const now = new Date().toISOString();
   133|  if (existing && !existing.verifiedAt && new Date(existing.expiresAt) >= new Date() && existing.resendCount >= MAX_RESENDS) {
   134|    throw new Error('Verification resend limit reached. Please wait for the current code to expire.');
   135|  }
   136|  codes[key] = {
   137|    userId: input.userId,
   138|    type: input.type,
   139|    codeHash: hashCode(code),
   140|    attempts: 0,
   141|    resendCount: existing && !existing.verifiedAt ? existing.resendCount + 1 : 0,
   142|    expiresAt: expiresAt.toISOString(),
   143|    verifiedAt: null,
   144|    createdAt: now,
   145|    lastSentAt: now,
   146|  };
   147|  await writeStore(CODES_FILE(), codes);
   148|}
