   150|async function fallbackMarkVerified(userId: string, type: 'email' | 'phone'): Promise<void> {
   151|  const statuses = await readStore<FallbackStatusStore>(STATUS_FILE(), {});
   152|  const current = statuses[userId] ?? { emailVerified: false, phoneVerified: false, updatedAt: '' };
   153|  statuses[userId] = {
   154|    emailVerified: type === 'email' ? true : current.emailVerified,
   155|    phoneVerified: type === 'phone' ? true : current.phoneVerified,
   156|    updatedAt: new Date().toISOString(),
   157|  };
   158|  await writeStore(STATUS_FILE(), statuses);
   159|}
   160|
   161|async function fallbackVerifyCode(input: VerifyCodeInput): Promise<VerificationResult> {
   162|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   163|  const key = codeKey(input.userId, input.type);
   164|  const record = codes[key];
   165|
   166|  if (!record || record.verifiedAt) {
   167|    return {
   168|      success: false,
   169|      message: 'No pending verification found. Please request a new code.',
   170|      verified: false,
   171|      deploymentMarker: DEPLOYMENT_MARKER,
   172|    };
   173|  }
   174|
   175|  if (new Date(record.expiresAt) < new Date()) {
   176|    return {
   177|      success: false,
   178|      message: 'Verification code has expired. Please request a new code.',
   179|      verified: false,
   180|      deploymentMarker: DEPLOYMENT_MARKER,
   181|    };
   182|  }
   183|
   184|  if (record.attempts >= MAX_ATTEMPTS) {
   185|    return {
   186|      success: false,
   187|      message: 'Too many failed attempts. Please request a new code.',
   188|      verified: false,
   189|      deploymentMarker: DEPLOYMENT_MARKER,
   190|    };
   191|  }
   192|
   193|  record.attempts += 1;
   194|
   195|  if (!matchesCode(input.code, record.codeHash)) {
   196|    codes[key] = record;
   197|    await writeStore(CODES_FILE(), codes);
   198|    const remaining = MAX_ATTEMPTS - record.attempts;
   199|    return {
   200|      success: false,
   201|      message: `Invalid code. ${remaining} attempt${remaining !== 1 ? 's' : ''} remaining.`,
   202|      verified: false,
   203|      deploymentMarker: DEPLOYMENT_MARKER,
   204|    };
   205|  }
   206|
   207|  record.verifiedAt = new Date().toISOString();
   208|  codes[key] = record;
   209|  await writeStore(CODES_FILE(), codes);
   210|  await fallbackMarkVerified(input.userId, input.type);
   211|
   212|  // Best-effort: also try updating the Supabase profile (ignored if the
   213|  // columns do not exist yet).
   214|  try {
   215|    const supabase = getSupabaseAdmin();
   216|    const verifiedField = input.type === 'email' ? 'email_verified' : 'phone_verified';
   217|    await supabase
   218|      .from('profiles')
   219|      .update({ [verifiedField]: true, updated_at: record.verifiedAt })
   220|      .eq('id', input.userId);
   221|  } catch {
   222|    // non-critical
   223|  }
   224|
   225|  return {
   226|    success: true,
   227|    message: `${input.type === 'email' ? 'Email' : 'Phone'} verified successfully`,
   228|    verified: true,
   229|    deploymentMarker: DEPLOYMENT_MARKER,
   230|  };
   231|}
