   318|export async function verifyCode(input: VerifyCodeInput): Promise<VerificationResult> {
   319|  const supabase = getSupabaseAdmin();
   320|
   321|  try {
   322|    const { data, error } = await supabase
   323|      .from('verification_codes')
   324|      .select('*')
   325|      .eq('user_id', input.userId)
   326|      .eq('type', input.type)
   327|      .is('verified_at', null)
   328|      .maybeSingle();
   329|
   330|    if (error) {
   331|      console.error('[MemberVerification] Supabase code lookup failed, checking fallback store:', error.message);
   332|      return fallbackVerifyCode(input);
   333|    }
   334|
   335|    const record = data as VerificationCodeRecord | null;
   336|
   337|    if (!record) {
   338|      // The code may live in the fallback store (schema missing at send time).
   339|      return fallbackVerifyCode(input);
   340|    }
   341|
   342|    // Check expiry
   343|    if (new Date(record.expires_at) < new Date()) {
   344|      return {
   345|        success: false,
   346|        message: 'Verification code has expired. Please request a new code.',
   347|        verified: false,
   348|        deploymentMarker: DEPLOYMENT_MARKER,
   349|      };
   350|    }
   351|
   352|    // Check attempts
   353|    if (record.attempts >= MAX_ATTEMPTS) {
   354|      return {
   355|        success: false,
   356|        message: 'Too many failed attempts. Please request a new code.',
   357|        verified: false,
   358|        deploymentMarker: DEPLOYMENT_MARKER,
   359|      };
   360|    }
   361|
   362|    // Increment attempts
   363|    const newAttempts = record.attempts + 1;
   364|
   365|    if (!matchesCode(input.code, record.code)) {
   366|      await supabase
   367|        .from('verification_codes')
   368|        .update({ attempts: newAttempts })
   369|        .eq('id', record.id);
   370|
   371|      const remaining = MAX_ATTEMPTS - newAttempts;
   372|      return {
   373|        success: false,
   374|        message: `Invalid code. ${remaining} attempt${remaining !== 1 ? 's' : ''} remaining.`,
   375|        verified: false,
   376|        deploymentMarker: DEPLOYMENT_MARKER,
   377|      };
   378|    }
   379|
   380|    // Code matches — mark verified
   381|    const now = new Date().toISOString();
   382|    await supabase
   383|      .from('verification_codes')
   384|      .update({ verified_at: now, attempts: newAttempts })
